  "philosophy-ex-philo_3as_lp_05-01": {
    "id": "philosophy-ex-philo_3as_lp_05-01",
    "subjectId": "philosophy",
    "subjectName": "الفلسفة",
    "type": "exercise",
    "lessonId": "philo_3as_lp_05",
    "lessonTitle": "العادة والإرادة",
    "title": "مقالة جدلية: هل التكيف مع العالم الخارجي يتحقق بالعادة أم بالإرادة؟",
    "year": null,
    "term": null,
    "level": "الثالثة ثانوي",
    "branch": "آداب وفلسفة",
    "badge": "تطبيق منهجي",
    "contentCase": "A",
    "problem": {
      "available": true,
      "format": "text",
      "text": "قيل: \"إن العادة تكسب الإنسان قدرة على التكيف لكنها في الوقت ذاته تقلص من فاعلية الإرادة\". حلل وناقش.",
      "url": "https://www.dzexams.com/ar/documents/Y2VCV0xFV3RoZGlsSWp6MTZ4V3gyZz09"
    },
    "solution": {
      "available": true,
      "format": "text",
      "text": "عناصر الإجابة وسلم التنقيط النموذجي المعتمد لشهادة البكالوريا",
      "markingScheme": [
        "طرح المشكلة (مدخل حول التكيف والسلوك المكتسب والعزم الواعي) [4 نقاط]",
        "الموقف الأول (التكيف يتم بالعادة كسلوك آلي موفر للجهد) [4 نقاط]",
        "الموقف الثاني (التكيف يتطلب الإرادة كوعي وقرار متجدد لمواجهة المواقف الطارئة) [4 نقاط]",
        "التركيب وحل المشكلة (التكامل الوظيفي بين العادة والإرادة) [4 نقاط]"
      ],
      "url": "https://www.dzexams.com/ar/documents/Y2VCV0xFV3RoZGlsSWp6MTZ4V3gyZz09"
    },
    "source": {
      "type": "official",
      "name": "التوجيه التربوي لمادة الفلسفة",
      "url": "https://www.dzexams.com/ar/documents/Y2VCV0xFV3RoZGlsSWp6MTZ4V3gyZz09",
      "verified": true
    }
  },
